    "187a157d": {"text":"{used}/{slots} occupied","hash":"h1-c295da46"},
    "18827885": {"text":"None of the three sounded-out families fits every limit and current resource gate.","hash":"h1-17b1a9ff"},
    "188b0e97": {"text":"The strips, ditches, and remembered bounds refuse to add up cleanly.","hash":"h1-a2b7d3c2"},
