    "3c7bdf65": {"text":"They will tire of it.","hash":"h1-fbd91fbf"},
    "3c844411": {"text":"Eligible worker","hash":"h1-18c701e2"},
    "3c98e321": {"text":"One exact offer is available.","hash":"h1-aae215bd"},
