    "3d390fb9": {"text":"— falls back to the bare rank when unlanded */ FB.styledTitle = function (state) { return FB.renderTitleSnapshot(FB.titleSnapshot(state)); }; FB.titleSnapshot = function (state) { const p = state.player; const me = state.chars[p.charId]; const rel = FB.religionOf(me.religion); let group = rel.group === 'muslim' ? 'muslim' : rel.group === 'pagan' ? 'pagan' : rel.group === 'jewish' ? 'jewish' : 'christian'; if (me.sex === 'f' && FBDATA.titles[group + '_f']) group += '_f'; const arr = FBDATA.titles[group] || FBDATA.titles.christian; const snap = { group: group, tier: FB.clamp(p.tier, 0, arr.length - 1) }; if (FB.playerPope && FB.playerPope(state)) { snap.special = 'pope'; return snap; } if (FB.playerCardinal && FB.playerCardinal(state)) { snap.special = 'cardinal'; return snap; } const headed = FB.religionsHeadedBy(state, 'player'); if (headed.length) { const headReligion = headed[0]; snap.headReligion = headReligion; snap.headTitle = FBDATA.religions[headReligion].head.title; return snap; } if (p.tier","hash":"h1-abdf56c5"},
    "3d3aee53": {"text":"🧰 Work, training & enterprises…","hash":"h1-061aa82e"},
