    "4e991347": {"text":"{slot}: {item}","hash":"h1-1b873711"},
    "4e9b6441": {"text":"Medina","hash":"h1-cde9c329"},
    "4e9d2179": {"text":"Personal character…","hash":"h1-953153dc"},
    "4e9ed421": {"text":"Take your seat in the settlement council or decide a final territorial grant.","hash":"h1-581a8a1f"},
    "4ea79db1": {"text":"Reset to Defaults","hash":"h1-fbed1331"},
    "4eb15c65": {"text":"Diplomacy wins trust and makes other people easier to persuade.","hash":"h1-948bf8de"},
    "4eb86331": {"text":"Sultana","hash":"h1-58969d6d"},
    "4ebe993b": {"text":"You shirk artfully and save your strength.","hash":"h1-4f337114"},
