    "573458e9": {"text":"That stake or market is not available.","hash":"h1-a5beeb6d"},
    "5746d7f5": {"text":"You leave the hall with three new friends and a standing invitation. Your name is warming in the realm.","hash":"h1-416f5f83"},
    "574849dd": {"text":"Spend {money:25}; the charter is guaranteed.","hash":"h1-03aad242"},
    "5749c6b5": {"text":"Part ways without a wedding. This costs no day.","hash":"h1-4fcd8a82"},
    "5751dfc1": {"text":"Family armory","hash":"h1-28874a09"},
    "575b08e1": {"text":"The offer was a test. Your reputation reaches the door before you do.","hash":"h1-d755ffb9"},
    "575e4023": {"text":"Heat Beneath the Blanket","hash":"h1-ab6ec530"},
    "5763069d": {"text":"First miss: 10% face penalty and two more seasons. Default: {consequence}","hash":"h1-61209ca6"},
    "57686ce1": {"text":"Some doors are better left unknocked.","hash":"h1-e5c810f1"},
    "576926d1": {"text":"Pay both millers and be done. ({money:4})","hash":"h1-c8c9c7b5"},
    "576da985": {"text":"Prior awards","hash":"h1-b855a1e3"},
    "5779fd71": {"text":"Royal Council","hash":"h1-f23a91c3"},
    "577a15e9": {"text":"The patron has paid less than half while claiming to have paid all.","hash":"h1-52ceed76"},
